using System;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using BongoChat;using BongoChat.Protocol;
public static class AutoChestTests
{
 static int checks;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static AutoChestLease Lease(string session,DateTime now){return new AutoChestLease{protocol=1,kind="auto_chests",owner=Guid.NewGuid().ToString("N"),session=session,enabled=true,createdUtc=now.ToString("o"),expiresUtc=now.AddSeconds(5).ToString("o")};}
 static void Select(ChatWindow w,string code){foreach(ComboBoxItem item in ((ComboBox)((Grid)w.Content).FindName("Language")).Items)if((string)item.Tag==code){((ComboBox)((Grid)w.Content).FindName("Language")).SelectedItem=item;return;}}
 [STAThread]public static int Main(string[] args){try{
  var now=DateTime.UtcNow;var lease=Lease("session",now);
  Check(AutoChestPolicy.Valid(lease,"session",now),"a fresh bounded lease is valid");Check(!AutoChestPolicy.Valid(lease,"other",now),"a game restart invalidates old permissions");Check(!AutoChestPolicy.Valid(lease,"session",now.AddSeconds(7)),"missing heartbeats expire within six seconds");
  lease.expiresUtc=now.AddMinutes(5).ToString("o");Check(!AutoChestPolicy.Valid(lease,"session",now),"a long-lived permission cannot enable unattended opening");lease=Lease("session",now.AddMinutes(1));Check(!AutoChestPolicy.Valid(lease,"session",now),"future permissions fail closed");lease=Lease("session",now);lease.owner="bad";Check(!AutoChestPolicy.Valid(lease,"session",now),"malformed lease owners fail closed");lease=Lease("session",now);lease.kind="send_chat";Check(!AutoChestPolicy.Valid(lease,"session",now),"chat commands cannot be interpreted as chest permissions");
  var gate=new AutoChestGate();var ready=new ChestReadiness{Ready=true,CanOpen=true};var unavailable=new ChestReadiness{Known=false};var notReady=new ChestReadiness();
  Check(gate.Next(false,ready,ready,0)==0,"automation starts off");Check(gate.Next(true,ready,ready,1)==1,"both-ready selection starts one normal chest");Check(gate.Next(true,ready,ready,1.1)==0,"a minimum attempt interval prevents simultaneous opening");Check(gate.Next(true,ready,ready,4)==2,"the emote chest follows without repeating the normal chest");Check(gate.Next(true,ready,ready,8)==0,"a sustained ready flag never repeats an uncertain request");
  gate.Next(true,unavailable,ready,9);Check(gate.Next(true,ready,ready,10)==0,"unknown UI state cannot rearm a prior attempt");gate.Next(true,notReady,ready,11);Check(gate.Next(true,ready,ready,12)==1,"only a real ready-to-not-ready cycle rearms a chest");
  string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);AppStorage.Root=root;string game=Path.Combine(root,"game"),folder=Path.Combine(game,"BepInEx","BongoChat");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(game,"BongoCat.exe"),"");
  var writer=new AutoChestLeaseWriter();var state=new BridgeState{protocol=1,session="session",utc=DateTime.UtcNow.ToString("o"),ready=true,autoChestSupported=true};
  writer.Write(game,state,true,writer.Revision);string file=Path.Combine(folder,"auto-chests.json");lease=Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file));Check(lease.enabled&&AutoChestPolicy.Valid(lease,"session",DateTime.UtcNow),"app writes a fresh five-second lease without requiring a room");
  int old=writer.Revision;writer.Invalidate();writer.Write(game,state,false,writer.Revision);writer.Write(game,state,true,old);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"an old background poll cannot overwrite a newer off request");
  state.autoChestSupported=false;writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"legacy bridges cannot receive enabled permission");state.autoChestSupported=true;state.utc=DateTime.UtcNow.AddMinutes(-1).ToString("o");writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"stale game state cannot authorize automation");state.utc=DateTime.UtcNow.ToString("o");state.protocol=99;writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"unknown bridge protocols cannot authorize opening");state.protocol=1;
  TabletCompatibility.Configure();new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};File.WriteAllText(Path.Combine(folder,"state.json"),Journal.Json.Serialize(state));
  var w=new ChatWindow(false,game,true,"ko");var grid=(Grid)w.Content;var toggle=(CheckBox)grid.FindName("AutoChests");var hint=(TextBlock)grid.FindName("AutoChestHint");
  Check(toggle.IsChecked==false&&hint.Text.Contains("꺼짐"),"UI defaults off with no automatic request");toggle.IsChecked=true;w.Poll();Check(Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"user opt-in renews permission even outside a chat room");
  Check(File.ReadAllText(Path.Combine(root,"auto-chests.txt"))=="true","the user preference is saved independently of game settings");Select(w,"en");Check(toggle.Content.ToString()=="Auto-open chests"&&hint.Text.Contains("Waiting"),"English labels switch immediately");Select(w,"ja");Check(toggle.Content.ToString()=="宝箱を自動で開く"&&hint.Text.Contains("待ち"),"Japanese labels switch immediately");
  w.Left=-10000;w.Top=-10000;w.WindowStartupLocation=WindowStartupLocation.Manual;w.ShowActivated=false;w.Show();w.Width=420;w.Height=w.MinHeight;w.UpdateLayout();var composer=(TextBox)typeof(ChatWindow).GetField("composer",flags).GetValue(w);var bottom=composer.TranslatePoint(new Point(composer.ActualWidth,composer.ActualHeight),grid);Check(bottom.Y<=grid.ActualHeight+1&&bottom.Y>0,"new controls retain the composer inside a narrow minimum-height layout");
  w.Width=510;w.Height=750;Select(w,"ko");w.Snapshot(Path.Combine(root,"auto-chests-ko.png"));Select(w,"en");w.Snapshot(Path.Combine(root,"auto-chests-en.png"));Select(w,"ja");w.Snapshot(Path.Combine(root,"auto-chests-ja.png"));
  toggle.IsChecked=false;Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"turning the option off immediately writes a disabled lease");toggle.IsChecked=true;w.Close();Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(file)).enabled,"closing the companion invalidates old polls and writes off");
  var reopened=new ChatWindow(false,game,true,"ko");Check(((CheckBox)((Grid)reopened.Content).FindName("AutoChests")).IsChecked==true,"saved opt-in survives app restart");reopened.Close();
  var demo=new ChatWindow(true,null,true,"en");Check(!((CheckBox)((Grid)demo.Content).FindName("AutoChests")).IsEnabled,"preview windows cannot automate the real game");demo.Close();
  Console.WriteLine("All "+checks+" auto-chest checks passed.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}